/**
 * EXTERNAL ORACLE. Do not edit this file, and do not regenerate
 * `fixtures/oracle-word-boxes.json`, to make a failure go away.
 *
 * Every other expectation in this repo descends from code in this repo, so a
 * consistent-but-wrong coordinate conversion would sail through its own tests.
 * `fixtures/oracle-word-boxes.json` holds 1996 word boxes measured by PyMuPDF,
 * a different library by different authors reading the same 20 PDFs in the same
 * convention (PDF points, top-left origin). It is the one check on `lib/pdf.ts`
 * that `lib/pdf.ts` did not produce.
 *
 * TOLERANCES ARE MEASURED, NOT CHOSEN. Calibration against the reader at commit
 * 2b551b0, matching oracle words to pdf.js text runs by centre containment:
 *
 *   located          1996 / 1996          page dimensions agree exactly
 *   |y0 diff|        p50 1.96  p95 2.41  p99 3.45  max 5.04
 *   |y1 diff|        p50 2.18  p95 3.00  p99 3.90  max 5.70
 *   |x0 diff|        p50 0.00  p95 157.77  p99 234.61  max 274.28
 *
 * The vertical spread is inherent: pdf.js reports a font-height box for a whole
 * text RUN, PyMuPDF a tight glyph box for one WORD. Hence a 6pt vertical budget.
 *
 * The horizontal spread is the point of the exercise. A run's left edge is
 * nowhere near a word late in that run, so per-word boxes are only possible once
 * a line records which characters each fragment covers. The p95 assertion below
 * is what separates a working span implementation from one that quietly falls
 * back to returning the whole line's box: today's fallback measures p95 = 158pt,
 * and no tolerance stretching will hide that.
 */

import { readFileSync } from 'node:fs'
import { describe, expect, it } from 'vitest'

import { boxFor } from '../src/lib/pdf'
import { readPdf } from '../src/lib/pdf'
import type { BBox, Line } from '../src/domain/types'

type OracleWord = { text: string; x0: number; y0: number; x1: number; y1: number }
type OraclePage = { page: number; width: number; height: number; words: OracleWord[] }

const oracle = JSON.parse(
  readFileSync(new URL('./fixtures/oracle-word-boxes.json', import.meta.url), 'utf8'),
) as { documents: Record<string, OraclePage[]> }

const VERTICAL_BUDGET = 6 // pt; measured max was 5.70
const HORIZONTAL_BUDGET = 6 // pt; a per-word box should do at least as well as a per-run box does vertically
const P95_HORIZONTAL = 3 // pt; the assertion a line-box fallback cannot pass

function pdf(file: string): Blob {
  return new Blob([readFileSync(new URL(`../public/sample/${file}`, import.meta.url))])
}

/** The oracle word's centre, used to pick which line and which run it sits in. */
function centre(w: OracleWord): { cx: number; cy: number } {
  return { cx: (w.x0 + w.x1) / 2, cy: (w.y0 + w.y1) / 2 }
}

function contains(b: BBox, cx: number, cy: number, pad = 2): boolean {
  return cx >= b.x - pad && cx <= b.x + b.width + pad && cy >= b.y - pad && cy <= b.y + b.height + pad
}

/**
 * Finds the assembled line holding this word and the word's character range
 * within `line.text`. Returns null when the word cannot be located, which the
 * caller counts rather than ignores.
 *
 * Matching is by position, not by string search: the same word often appears
 * several times on an invoice, and a search would silently pick the wrong one.
 */
function locate(lines: Line[], w: OracleWord): { line: Line; start: number; end: number } | null {
  const { cx, cy } = centre(w)
  const line = lines.find((l) => contains(l.bbox, cx, cy))
  if (!line) return null

  const needle = w.text.trim()
  if (needle === '') return null

  // Among every occurrence of the word's text in this line, take the one whose
  // own computed box is nearest the oracle's horizontal position.
  let best: { start: number; end: number; dist: number } | null = null
  for (let i = line.text.indexOf(needle); i !== -1; i = line.text.indexOf(needle, i + 1)) {
    const box = boxFor(line, i, i + needle.length)
    if (!box) continue
    const dist = Math.abs(box.x - w.x0)
    if (!best || dist < best.dist) best = { start: i, end: i + needle.length, dist }
  }
  return best ? { line, start: best.start, end: best.end } : null
}

describe('PyMuPDF oracle: per-word provenance boxes', () => {
  const files = Object.keys(oracle.documents)

  it('has an oracle for all 20 text-layer invoices', () => {
    expect(files).toHaveLength(20)
    expect(Object.values(oracle.documents).flatMap((p) => p.flatMap((x) => x.words))).toHaveLength(1996)
  })

  it('agrees with PyMuPDF on every word box, and tightly on the horizontal', async () => {
    const dx: number[] = []
    let words = 0
    let unlocated = 0
    const failures: string[] = []

    for (const file of files) {
      const pages = await readPdf(pdf(file), file)
      for (const op of oracle.documents[file]) {
        const gp = pages.find((p) => p.page === op.page)
        expect(gp, `${file} page ${op.page} missing from the reader`).toBeDefined()
        expect(Math.abs(gp!.width - op.width)).toBeLessThan(0.5)
        expect(Math.abs(gp!.height - op.height)).toBeLessThan(0.5)

        for (const w of op.words) {
          words++
          const hit = locate(gp!.lines, w)
          if (!hit) {
            unlocated++
            continue
          }
          const box = boxFor(hit.line, hit.start, hit.end)
          if (!box) {
            unlocated++
            continue
          }
          dx.push(Math.abs(box.x - w.x0))

          const bad =
            Math.abs(box.x - w.x0) > HORIZONTAL_BUDGET ||
            Math.abs(box.x + box.width - w.x1) > HORIZONTAL_BUDGET ||
            Math.abs(box.y - w.y0) > VERTICAL_BUDGET ||
            Math.abs(box.y + box.height - w.y1) > VERTICAL_BUDGET
          if (bad && failures.length < 12) {
            failures.push(
              `${file} p${op.page} "${w.text}" oracle=(${w.x0},${w.y0})-(${w.x1},${w.y1}) ` +
                `got=(${box.x.toFixed(2)},${box.y.toFixed(2)})-(${(box.x + box.width).toFixed(2)},${(box.y + box.height).toFixed(2)})`,
            )
          }
        }
      }
    }

    // A word the implementation cannot point at is a silent gap in the product's
    // central promise, so a handful is tolerated and a systematic failure is not.
    expect(unlocated / words, `${unlocated} of ${words} words could not be located`).toBeLessThan(0.02)
    expect(failures.join('\n')).toBe('')

    const sorted = dx.slice().sort((a, b) => a - b)
    const p95 = sorted[Math.floor(sorted.length * 0.95)]
    // The measured line-box fallback sits at 158pt. Passing this means the span
    // mechanic genuinely resolves single words, not that a tolerance was widened.
    expect(p95, `p95 horizontal error ${p95?.toFixed(2)}pt`).toBeLessThan(P95_HORIZONTAL)
  }, 180_000)
})
